"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { useForm, useWatch } from "react-hook-form";
import * as z from "zod";
import { useState, useTransition } from "react";
import { format, differenceInYears } from "date-fns";

import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Checkbox } from "@/components/ui/checkbox";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import { findSacramentDateAction } from "@/app/actions";
import type { FindSacramentDateOutput } from "@/ai/flows/sacrament-date-finder";
import { Label } from "@/components/ui/label";

import {
  User,
  CalendarDays,
  HeartHandshake,
  Sparkles,
  Loader2,
  Users,
  Church,
  Baby
} from "lucide-react";
import { CrossIcon, DoveIcon, ChaliceIcon } from "@/components/icons";

const participantSchema = z.object({
  fullName: z.string().min(3, "Full name must be at least 3 characters."),
  dob: z.date({ required_error: "Date of birth is required." }),
  address: z.string().min(5, "Address is required."),
  phone: z.string().min(7, "A valid phone number is required."),
  maritalStatus: z.enum(["Single", "Divorced", "Widowed", "Married (Civil)"], {
    required_error: "Marital status is required.",
  }),
  previouslyMarried: z.enum(["Yes", "No"], { required_error: "Please select an option." }),
  parish: z.string().min(3, "Parish is required."),
  sacraments: z.object({
    baptism: z.boolean().default(false),
    baptismDate: z.string().optional(),
    firstCommunion: z.boolean().default(false),
    firstCommunionDate: z.string().optional(),
    confirmation: z.boolean().default(false),
    confirmationDate: z.string().optional(),
  }),
});

const formSchema = z.object({
  groom: participantSchema,
  bride: participantSchema,
  datingDuration: z.string().min(1, "This field is required."),
  liveTogether: z.enum(["Yes", "No"], { required_error: "Please select an option." }),
  timeLivingTogether: z.string().optional(),
  weddingDate: z.date().optional(),
  childrenInCommon: z.coerce.number().min(0).optional(),
  groomChildren: z.coerce.number().min(0).optional(),
  brideChildren: z.coerce.number().min(0).optional(),
});

type FormValues = z.infer<typeof formSchema>;
type ParticipantKey = "groom" | "bride";
type SacramentType = "Baptism" | "First Communion" | "Confirmation";

type SacramentFinderState = {
  open: boolean;
  participantKey: ParticipantKey | null;
  sacramentType: SacramentType | null;
  participantName: string;
};

function calculateAge(dob: Date | undefined): number | null {
    if (!dob) return null;
    return differenceInYears(new Date(), dob);
}


function SacramentFinderDialog({
  state,
  onClose,
  onDateFound,
  dictionary
}: {
  state: SacramentFinderState;
  onClose: () => void;
  onDateFound: (result: FindSacramentDateOutput) => void;
  dictionary: any;
}) {
  const [isPending, startTransition] = useTransition();
  const { toast } = useToast();

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const approximateYear = formData.get("approximateYear") as string;
    const location = formData.get("location") as string;

    if (!state.participantKey || !state.sacramentType || !state.participantName) return;

    startTransition(async () => {
      try {
        const result = await findSacramentDateAction({
          name: state.participantName,
          sacramentType: state.sacramentType,
          approximateYear,
          location,
        });
        onDateFound(result);
        toast({
          title: dictionary.toast.success.title,
          description: `${dictionary.toast.success.description1} ${state.sacramentType} ${dictionary.toast.success.description2} ${result.confidenceLevel * 100}% ${dictionary.toast.success.description3}`,
        });
        onClose();
      } catch (error) {
        toast({
          variant: "destructive",
          title: dictionary.toast.error.title,
          description: dictionary.toast.error.description,
        });
      }
    });
  };

  return (
    <Dialog open={state.open} onOpenChange={onClose}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="font-headline">
            {dictionary.title}: {state.sacramentType}
          </DialogTitle>
          <DialogDescription>
            {dictionary.description} {state.participantName}.
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="approximateYear">{dictionary.approximateYearLabel}</Label>
            <Input
              id="approximateYear"
              name="approximateYear"
              placeholder={dictionary.approximateYearPlaceholder}
              required
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="location">{dictionary.locationLabel}</Label>
            <Input
              id="location"
              name="location"
              placeholder={dictionary.locationPlaceholder}
              required
            />
          </div>
          <DialogFooter>
            <Button type="button" variant="ghost" onClick={onClose} disabled={isPending}>
              {dictionary.cancelButton}
            </Button>
            <Button type="submit" disabled={isPending}>
              {isPending ? <Loader2 className="animate-spin" /> : dictionary.findButton}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}


function ParticipantCard({
  participantKey,
  title,
  form,
  onFindSacrament,
  dictionary,
  gender
}: {
  participantKey: ParticipantKey;
  title: string;
  form: any;
  onFindSacrament: (
    participantKey: ParticipantKey,
    sacramentType: SacramentType
  ) => void;
  dictionary: any;
  gender: 'male' | 'female'
}) {

  const watchedSacraments = useWatch({
    control: form.control,
    name: `${participantKey}.sacraments`
  });
  
  const dob = useWatch({
    control: form.control,
    name: `${participantKey}.dob`
  });
  const age = calculateAge(dob);

  const placeholders = gender === 'male' ? dictionary.placeholders.groom : dictionary.placeholders.bride;

  const sacramentFields: {
    key: "baptism" | "firstCommunion" | "confirmation";
    label: SacramentType;
    Icon: React.ElementType;
  }[] = [
    { key: "baptism", label: "Baptism", Icon: CrossIcon },
    { key: "firstCommunion", label: "First Communion", Icon: ChaliceIcon },
    { key: "confirmation", label: "Confirmation", Icon: DoveIcon },
  ];

  return (
    <Card className="overflow-hidden">
      <CardHeader>
        <CardTitle className="font-headline text-2xl flex items-center gap-2">
          <User /> {title}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <FormField
            control={form.control}
            name={`${participantKey}.fullName`}
            render={({ field }) => (
              <FormItem>
                <FormLabel>{dictionary.fullName}</FormLabel>
                <FormControl>
                  <Input placeholder={placeholders.fullName} {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name={`${participantKey}.dob`}
            render={({ field }) => (
              <FormItem className="flex flex-col">
                <FormLabel>{dictionary.dob}</FormLabel>
                <Popover>
                  <PopoverTrigger asChild>
                    <FormControl>
                      <Button
                        variant={"outline"}
                        className={cn(
                          "w-full pl-3 text-left font-normal",
                          !field.value && "text-muted-foreground"
                        )}
                      >
                        {field.value ? (
                          <span>{format(field.value, "PPP")} {age !== null ? `(${age} ${dictionary.yearsOld})` : ''}</span>
                        ) : (
                          <span>{dictionary.pickADate}</span>
                        )}
                        <CalendarDays className="ml-auto h-4 w-4 opacity-50" />
                      </Button>
                    </FormControl>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0" align="start">
                    <Calendar
                      mode="single"
                      selected={field.value}
                      onSelect={(date) => {
                        field.onChange(date);
                      }}
                      disabled={(date) =>
                        date > new Date() || date < new Date("1900-01-01")
                      }
                      initialFocus
                    />
                  </PopoverContent>
                </Popover>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name={`${participantKey}.address`}
            render={({ field }) => (
              <FormItem>
                <FormLabel>{dictionary.address}</FormLabel>
                <FormControl>
                  <Input placeholder={placeholders.address} {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name={`${participantKey}.phone`}
            render={({ field }) => (
              <FormItem>
                <FormLabel>{dictionary.phone}</FormLabel>
                <FormControl>
                  <Input placeholder={placeholders.phone} {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name={`${participantKey}.maritalStatus`}
            render={({ field }) => (
              <FormItem>
                <FormLabel>{dictionary.maritalStatus}</FormLabel>
                <Select
                  onValueChange={field.onChange}
                  defaultValue={field.value}
                >
                  <FormControl>
                    <SelectTrigger>
                      <SelectValue placeholder={dictionary.maritalStatusPlaceholder} />
                    </SelectTrigger>
                  </FormControl>
                  <SelectContent>
                    <SelectItem value="Single">{gender === 'male' ? dictionary.maritalStatusOptions.single_male : dictionary.maritalStatusOptions.single_female}</SelectItem>
                    <SelectItem value="Divorced">{gender === 'male' ? dictionary.maritalStatusOptions.divorced_male : dictionary.maritalStatusOptions.divorced_female}</SelectItem>
                    <SelectItem value="Widowed">{gender === 'male' ? dictionary.maritalStatusOptions.widowed_male : dictionary.maritalStatusOptions.widowed_female}</SelectItem>
                    <SelectItem value="Married (Civil)">{gender === 'male' ? dictionary.maritalStatusOptions.civil_male : dictionary.maritalStatusOptions.civil_female}</SelectItem>
                  </SelectContent>
                </Select>
                <FormMessage />
              </FormItem>
            )}
          />
           <FormField
            control={form.control}
            name={`${participantKey}.parish`}
            render={({ field }) => (
              <FormItem>
                <FormLabel>{dictionary.parish}</FormLabel>
                <FormControl>
                  <Input placeholder={placeholders.parish} {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
              control={form.control}
              name={`${participantKey}.previouslyMarried`}
              render={({ field }) => (
                <FormItem className="space-y-3">
                  <FormLabel>{dictionary.previouslyMarried}</FormLabel>
                  <FormControl>
                    <RadioGroup
                      onValueChange={field.onChange}
                      defaultValue={field.value}
                      className="flex flex-col space-y-1"
                    >
                      <FormItem className="flex items-center space-x-3 space-y-0">
                        <FormControl>
                          <RadioGroupItem value="Yes" />
                        </FormControl>
                        <FormLabel className="font-normal">
                          {dictionary.yes}
                        </FormLabel>
                      </FormItem>
                      <FormItem className="flex items-center space-x-3 space-y-0">
                        <FormControl>
                          <RadioGroupItem value="No" />
                        </FormControl>
                        <FormLabel className="font-normal">
                          {dictionary.no}
                        </FormLabel>
                      </FormItem>
                    </RadioGroup>
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
        </div>
        <div className="space-y-4 pt-4 border-t">
          <h3 className="text-lg font-semibold font-headline">{dictionary.sacramentalHistory}</h3>
          {sacramentFields.map(({ key, label, Icon }) => (
             <FormField
              key={key}
              control={form.control}
              name={`${participantKey}.sacraments.${key}`}
              render={({ field }) => (
                <FormItem className="flex flex-row items-start space-x-3 space-y-0 rounded-md border p-4">
                  <FormControl>
                    <Checkbox
                      checked={field.value}
                      onCheckedChange={field.onChange}
                    />
                  </FormControl>
                  <div className="space-y-1 leading-none w-full">
                    <FormLabel className="flex items-center gap-2">
                      <Icon className="h-5 w-5" /> {dictionary.sacraments[key]} {dictionary.received}
                    </FormLabel>
                    {watchedSacraments?.[key] && (
                        <div className="flex items-center gap-2 pt-2">
                            <Input
                                disabled
                                value={form.getValues(`${participantKey}.sacraments.${key}Date`) || dictionary.noDateSet}
                                className="flex-grow"
                            />
                            <Button
                                type="button"
                                size="sm"
                                variant="outline"
                                onClick={() => onFindSacrament(participantKey, label)}
                            >
                                <Sparkles className="mr-2 h-4 w-4" /> {dictionary.findDate}
                            </Button>
                        </div>
                    )}
                  </div>
                </FormItem>
              )}
            />
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

export default function EnrollmentForm({ dictionary }: { dictionary: any }) {
  const { toast } = useToast();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [dialogState, setDialogState] = useState<SacramentFinderState>({
    open: false,
    participantKey: null,
    sacramentType: null,
    participantName: "",
  });

  const form = useForm<FormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      groom: {
        fullName: "",
        address: "",
        phone: "",
        parish: "",
        sacraments: {
          baptism: false,
          firstCommunion: false,
          confirmation: false,
        },
      },
      bride: {
        fullName: "",
        address: "",
        phone: "",
        parish: "",
        sacraments: {
          baptism: false,
          firstCommunion: false,
          confirmation: false,
        },
      },
      datingDuration: "",
      childrenInCommon: 0,
      groomChildren: 0,
      brideChildren: 0,
    },
  });

  const liveTogether = useWatch({
    control: form.control,
    name: "liveTogether",
  });

  function onSubmit(values: FormValues) {
    setIsSubmitting(true);
    console.log(values);
    // Simulate API call
    setTimeout(() => {
      toast({
        title: dictionary.submitToast.title,
        description: dictionary.submitToast.description,
      });
      setIsSubmitting(false);
    }, 1500);
  }

  const handleFindSacrament = (
    participantKey: ParticipantKey,
    sacramentType: SacramentType
  ) => {
    const participantName = form.getValues(`${participantKey}.fullName`);
    if (!participantName) {
      toast({
        variant: "destructive",
        title: dictionary.missingNameToast.title,
        description: dictionary.missingNameToast.description,
      });
      return;
    }
    setDialogState({
      open: true,
      participantKey,
      sacramentType,
      participantName,
    });
  };

  const handleDateFound = (result: FindSacramentDateOutput) => {
    if (dialogState.participantKey && dialogState.sacramentType) {
        const sacramentKey = dialogState.sacramentType === "Baptism" ? "baptismDate" : dialogState.sacramentType === "First Communion" ? "firstCommunionDate" : "confirmationDate";
        form.setValue(
            `${dialogState.participantKey}.sacraments.${sacramentKey}`,
            result.sacramentDate
        );
    }
  };

  return (
    <>
      <SacramentFinderDialog
        state={dialogState}
        onClose={() => setDialogState((prev) => ({ ...prev, open: false }))}
        onDateFound={handleDateFound}
        dictionary={dictionary.sacramentFinderDialog}
      />
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-8">
          <div className="space-y-8">
            <ParticipantCard
              participantKey="groom"
              title={dictionary.groom}
              form={form}
              onFindSacrament={handleFindSacrament}
              dictionary={dictionary.participantCard}
              gender="male"
            />
            <ParticipantCard
              participantKey="bride"
              title={dictionary.bride}
              form={form}
              onFindSacrament={handleFindSacrament}
              dictionary={dictionary.participantCard}
              gender="female"
            />
          </div>

          <Card>
            <CardHeader>
              <CardTitle className="font-headline text-2xl flex items-center gap-2">
                <Users /> {dictionary.relationshipInfo.title}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <FormField
                  control={form.control}
                  name="datingDuration"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>{dictionary.relationshipInfo.datingDuration}</FormLabel>
                      <FormControl>
                        <Input placeholder={dictionary.relationshipInfo.datingDurationPlaceholder} {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="weddingDate"
                  render={({ field }) => (
                    <FormItem className="flex flex-col">
                      <FormLabel>{dictionary.relationshipInfo.weddingDateSet}</FormLabel>
                       <Popover>
                  <PopoverTrigger asChild>
                    <FormControl>
                      <Button
                        variant={"outline"}
                        className={cn(
                          "w-full pl-3 text-left font-normal",
                          !field.value && "text-muted-foreground"
                        )}
                      >
                        {field.value ? (
                          format(field.value, "PPP")
                        ) : (
                          <span>{dictionary.relationshipInfo.pickWeddingDate}</span>
                        )}
                        <HeartHandshake className="ml-auto h-4 w-4 opacity-50" />
                      </Button>
                    </FormControl>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0" align="start">
                    <Calendar
                      mode="single"
                      selected={field.value}
                      onSelect={field.onChange}
                      initialFocus
                    />
                  </PopoverContent>
                </Popover>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>

               <FormField
                  control={form.control}
                  name="liveTogether"
                  render={({ field }) => (
                    <FormItem className="space-y-3">
                      <FormLabel>{dictionary.relationshipInfo.liveTogether}</FormLabel>
                      <FormControl>
                        <RadioGroup
                          onValueChange={field.onChange}
                          defaultValue={field.value}
                          className="flex flex-row space-x-4"
                        >
                          <FormItem className="flex items-center space-x-3 space-y-0">
                            <FormControl>
                              <RadioGroupItem value="Yes" />
                            </FormControl>
                            <FormLabel className="font-normal">
                              {dictionary.relationshipInfo.yes}
                            </FormLabel>
                          </FormItem>
                          <FormItem className="flex items-center space-x-3 space-y-0">
                            <FormControl>
                              <RadioGroupItem value="No" />
                            </FormControl>
                            <FormLabel className="font-normal">
                              {dictionary.relationshipInfo.no}
                            </FormLabel>
                          </FormItem>
                        </RadioGroup>
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                
                {liveTogether === "Yes" && (
                    <FormField
                      control={form.control}
                      name="timeLivingTogether"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>{dictionary.relationshipInfo.timeLivingTogether}</FormLabel>
                          <FormControl>
                            <Input placeholder={dictionary.relationshipInfo.timeLivingTogetherPlaceholder} {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                )}
            </CardContent>
          </Card>

           <Card>
            <CardHeader>
              <CardTitle className="font-headline text-2xl flex items-center gap-2">
                <Baby /> {dictionary.childrenInfo.title}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <FormField
                  control={form.control}
                  name="childrenInCommon"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>{dictionary.childrenInfo.inCommon}</FormLabel>
                      <FormControl>
                        <Input type="number" min="0" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="groomChildren"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>{dictionary.childrenInfo.groom}</FormLabel>
                      <FormControl>
                        <Input type="number" min="0" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                 <FormField
                  control={form.control}
                  name="brideChildren"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>{dictionary.childrenInfo.bride}</FormLabel>
                      <FormControl>
                        <Input type="number" min="0" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>
            </CardContent>
          </Card>


          <div className="flex justify-end">
            <Button type="submit" size="lg" disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {dictionary.submitButton}
            </Button>
          </div>
        </form>
      </Form>
    </>
  );
}
