'use client';

import EnrollmentForm from '@/components/app/enrollment-form';
import type { Locale } from '@/lib/i-18n-config';
import { useAuth } from '@/hooks/use-auth';
import { useRouter } from 'next/navigation';

export default function HomeClient({
  lang,
  dictionary,
}: {
  lang: Locale;
  dictionary: any;
}) {
  const { isAuthenticated } = useAuth();

  // The middleware should handle all redirection logic.
  // This component will only render if the user is authenticated.
  if (!isAuthenticated) {
    // This is a fallback and ideally should not be reached.
    return null;
  }

  return (
    <main className="flex min-h-screen flex-col items-center bg-background py-12 px-4 sm:px-6 lg:px-8">
      <div className="w-full max-w-5xl space-y-8">
        <header className="text-center pt-8">
          <h1 className="font-headline text-4xl font-bold tracking-tight text-foreground sm:text-5xl md:text-6xl">
            {dictionary.page.title}
          </h1>
          <p className="mt-4 font-body text-lg text-muted-foreground">
            {dictionary.page.description}
          </p>
        </header>
        <EnrollmentForm dictionary={dictionary.form} />
      </div>
    </main>
  );
}
